template <class V> struct Node : NodeBase { V value; };

template <class V> static Node<V>* CloneNode(Node<V>* x)
{
    Node<V>* t = (Node<V>*)std::malloc(sizeof(Node<V>));
    new (&t->value) V(x->value);
    t->color = x->color; t->left = 0; t->right = 0;
